pub static GL_FX: [i32; 16] = [
    0, 18, 24, 3,
    18, 11, 16, 2,
    29, 6, 12, 3,
    35, 9, 16, 3
];
pub(crate) fn gl_begin(mut t: &mut String, pr: i32, started: i32, code: i32) -> i32 {
    if started == 1 {
        crate::port::text_ascii(t, ",");
    }
    if pr == 1 {
        js_indent(t, 3);
    }
    crate::port::text_ascii(t, "\"");
    glk_emit_name(t, code);
    crate::port::text_ascii(t, "\":");
    if pr == 1 {
        crate::port::text_ascii(t, " ");
    }
    return 1;
}
pub(crate) fn gl_bits(mut t: &mut String, pr: i32, v: i32, which: i32) -> i32 {
    // A bit set as an array of names (which 10 `gq`, 11 `gqf`, 12 `gs`).
    let mut b: i32 = 0;
    let mut k: i32 = 0;
    let mut bit: i32 = 1;
    crate::port::text_ascii(t, "[");
    while b < 16 {
        if (v & bit) != 0 {
            js_fsep(t, pr, k);
            crate::port::text_ascii(t, "\"");
            if which == 10 {
                gq_emit_name(t, bit);
            }
            if which == 11 {
                gqf_emit_name(t, bit);
            }
            if which == 12 {
                gs_emit_name(t, bit);
            }
            crate::port::text_ascii(t, "\"");
            k += 1;
        }
        bit *= 2;
        b += 1;
    }
    crate::port::text_ascii(t, "]");
    return 0;
}
pub(crate) fn gl_field(mut t: &mut String, pr: i32, c: &mut crate::port::Cells, stride: i32, row: i32, r: i32, started: i32) -> i32 {
    // One printed field of a row, by row `r` of `gl-fd`.
    let f: i32 = GL_FD[(r * 6 + 1) as usize];
    let kind: i32 = GL_FD[(r * 6 + 2) as usize];
    let key: i32 = GL_FD[(r * 6 + 3) as usize];
    let dflt: i32 = GL_FD[(r * 6 + 4) as usize];
    let arg: i32 = GL_FD[(r * 6 + 5) as usize];
    let p: i32 = (row * stride) + f;
    let mut s: i32 = started;
    if ((kind == 1) || ((kind == 2) || (((kind >= 6) && (kind <= 9)) || (kind >= 10)))) && (crate::port::cells_at(c, p) == dflt) {
        return started;
    }
    if kind == 1 {
        s = gl_begin(t, pr, s, key);
        crate::port::text_i32(t, crate::port::cells_at(c, p));
        return s;
    }
    if kind == 2 {
        s = gl_begin(t, pr, s, key);
        js_cpt(t, crate::port::cells_at(c, p));
        return s;
    }
    if kind == 3 {
        s = gl_begin(t, pr, s, key);
        crate::port::text_ascii(t, "[");
        js_cpt(t, crate::port::cells_at(c, p));
        js_fsep(t, pr, 1);
        js_cpt(t, crate::port::cells_at(c, p + 1));
        js_fsep(t, pr, 1);
        js_cpt(t, crate::port::cells_at(c, p + 2));
        js_fsep(t, pr, 1);
        js_cpt(t, crate::port::cells_at(c, p + 3));
        crate::port::text_ascii(t, "]");
        return s;
    }
    if kind == 4 {
        if (crate::port::cells_at(c, p) == dflt) && (crate::port::cells_at(c, p + 1) == arg) {
            return started;
        }
        s = gl_begin(t, pr, s, key);
        crate::port::text_ascii(t, "[");
        crate::port::text_i32(t, crate::port::cells_at(c, p));
        js_fsep(t, pr, 1);
        crate::port::text_i32(t, crate::port::cells_at(c, p + 1));
        crate::port::text_ascii(t, "]");
        return s;
    }
    if kind == 5 {
        if crate::port::cells_at(c, p + 1) == dflt {
            return started;
        }
        s = gl_begin(t, pr, s, key);
        crate::port::text_ascii(t, "[\"");
        ea_emit_name(t, crate::port::cells_at(c, p));
        crate::port::text_ascii(t, "\",");
        if pr == 1 {
            crate::port::text_ascii(t, " ");
        }
        crate::port::text_i32(t, crate::port::cells_at(c, p + 1));
        crate::port::text_ascii(t, "]");
        return s;
    }
    if (kind >= 6) && (kind <= 9) {
        s = gl_begin(t, pr, s, key);
        crate::port::text_ascii(t, "\"");
        if kind == 6 {
            go_emit_name(t, crate::port::cells_at(c, p));
        }
        if kind == 7 {
            rs_emit_name(t, crate::port::cells_at(c, p));
        }
        if kind == 8 {
            gk_emit_name(t, crate::port::cells_at(c, p));
        }
        if kind == 9 {
            rk_emit_name(t, crate::port::cells_at(c, p));
        }
        crate::port::text_ascii(t, "\"");
        return s;
    }
    if kind >= 10 {
        s = gl_begin(t, pr, s, key);
        gl_bits(t, pr, crate::port::cells_at(c, p), kind);
        return s;
    }
    return started;
}
pub(crate) fn gl_row(mut t: &mut String, pr: i32, a: i32, c: &mut crate::port::Cells, row: i32) -> i32 {
    // One row of arena a (1 `grl` .. 4 `grg`) as an object, its fields in stride order.
    let first: i32 = GL_FX[((a - 1) * 4 + 0) as usize];
    let cnt: i32 = GL_FX[((a - 1) * 4 + 1) as usize];
    let stride: i32 = GL_FX[((a - 1) * 4 + 2) as usize];
    let mut s: i32 = 0;
    let mut k: i32 = 0;
    crate::port::text_ascii(t, "{");
    while k < cnt {
        s = gl_field(t, pr, c, stride, row, first + k, s);
        k += 1;
    }
    js_close(t, pr, 2, s);
    return 0;
}
pub fn gl_arena(mut t: &mut String, pr: i32, started: i32, a: i32, c: &mut crate::port::Cells) -> i32 {
    // `"key":[row, ...]` for arena a (1 `grl`, 2 `gfl`, 3 `ggp`, 4 `grg`), as a member of the dump's object; answers 1.
    let stride: i32 = GL_FX[((a - 1) * 4 + 2) as usize];
    let n: i32 = crate::port::cells_len(c) / stride;
    let mut i: i32 = 0;
    if started == 1 {
        crate::port::text_ascii(t, ",");
    }
    if pr == 1 {
        js_indent(t, 1);
    }
    crate::port::text_ascii(t, "\"");
    glk_emit_name(t, a);
    crate::port::text_ascii(t, "\":");
    if pr == 1 {
        crate::port::text_ascii(t, " ");
    }
    crate::port::text_ascii(t, "[");
    while i < n {
        js_aelem(t, pr, 1, i);
        gl_row(t, pr, a, c, i);
        i += 1;
    }
    js_aend(t, pr, 1, n);
    return 1;
}
pub fn gl_emit(mut t: &mut String, pretty: i32, s0: i32, grl: &mut crate::port::Cells, gfl: &mut crate::port::Cells, ggp: &mut crate::port::Cells, grg: &mut crate::port::Cells) -> i32 {
    // The four arrays as members of the dump's object, `s0` being 1 when a member came before. Answers 1.
    let mut s: i32 = s0;
    s = gl_arena(t, pretty, s, 1, grl);
    s = gl_arena(t, pretty, s, 2, gfl);
    s = gl_arena(t, pretty, s, 3, ggp);
    s = gl_arena(t, pretty, s, 4, grg);
    return s;
}
